      </Button>
      <Button
        onClick={handleSave}
        variant="outline"
        size="sm"
        className="gap-1.5"
        disabled={saveState === "working"}
      >
        {saveState === "done" ? (
          <>
            <Check className="size-3.5" />
            Saved!
          </>
        ) : (
          <>
            <Download className="size-3.5" />
            {saveState === "working" ? "Saving..." : "Save"}
          </>
        )}
      </Button>
    </div>
  );
}

