      type: "value",
      axisLine: { show: false },
      axisTick: { show: false },
      splitLine: {
        lineStyle: { color: resolveChartColorAlpha("--border", 0.5) },
      },
    },
    yAxis: {
      type: "category",
      data: top.map((d) => d.toolName),
      axisLine: { show: false },
      axisTick: { show: false },
    },
    series: [
      {
        name: "Uses",
        type: "bar",
        data: top.map((d) => d.count),
        barMaxWidth: 20,
        itemStyle: {
          color: resolveChartColor("--chart-1"),
