  return (
    <Card className="gap-3 py-4">
      <CardHeader className="px-4">
        <CardTitle>Tool Usage (Top 10)</CardTitle>
      </CardHeader>
      <CardContent className="px-4">
        <EChart option={option} style={{ height }} />
      </CardContent>
    </Card>
  );
}

