"use client";

import { Boxes, Code, DollarSign, Zap } from "lucide-react";
import { CardError } from "@/components/card-error";
import { CardLoading } from "@/components/card-loading";
import { StatCard } from "@/components/stat-card";
import { formatValue } from "@/lib/format";
import type { StatCardsProps } from "./types";
import { useService } from "./use-service";

export function StatCards({ timeRange }: StatCardsProps) {
  const { stats, isLoading, error, refetch } = useService(timeRange);

  if (isLoading) {
    return (
      <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-4">
        {Array.from({ length: 4 }).map((_, i) => (<CardLoading key={i} />))}
      </div>
    );
  }

  if (error) {
    return (
      <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-4">
        <CardError message="Failed to load statistics" onRetry={() => refetch()} className="col-span-full" />
      </div>
    );
  }

  const cost = formatValue(stats.totalCost, "currency");
  const tokens = formatValue(stats.totalTokens, "number");
  const changePercent = stats.costChangePercent !== 0
    ? `${stats.costChangePercent >= 0 ? "+" : ""}${stats.costChangePercent.toFixed(0)}% vs last`
    : undefined;

  let costDescription = changePercent;
  if (timeRange === "month") {
    const now = new Date();
    const daysPassed = now.getDate();
    const daysInMonth = new Date(now.getFullYear(), now.getMonth() + 1, 0).getDate();
    const projectedCost = daysPassed > 0 ? (stats.totalCost / daysPassed) * daysInMonth : 0;
    const projected = formatValue(projectedCost, "currency");
    costDescription = changePercent
      ? `${changePercent} · Projected: ${projected.full}`
      : `Projected: ${projected.full}`;
  }

  return (
    <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-4">
      <StatCard title="Total Cost" value={cost.full} description={costDescription} icon={<DollarSign className="size-4" />} color="emerald" />
      <StatCard title="Tokens" value={tokens.value} unit={tokens.unit} description={`${stats.cachePercentage.toFixed(0)}% from cache`} icon={<Zap className="size-4" />} color="blue" />
      <StatCard title="Lines Changed" value={formatValue(stats.linesOfCodeAdded + stats.linesOfCodeRemoved, "number").full} description={`+${formatValue(stats.linesOfCodeAdded, "number").full} / -${formatValue(stats.linesOfCodeRemoved, "number").full}`} icon={<Code className="size-4" />} color="violet" />
      <StatCard title="Sessions" value={stats.totalSessions.toString()} description={`+${stats.todaySessions} today`} icon={<Boxes className="size-4" />} color="amber" />
    </div>
  );
}
```

4 stat cards in a grid: Total Cost (with month projection), Tokens (with cache %), Lines Changed (with +/-), Sessions (with today count).

